INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_ITA_PICUS_VIRGIL','ENT_ITA_PICUS','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 7.48:','But Faunus came from Picus: Picus drew His birth from Saturn, if records be true. Thus King Latinus, in the third degree, Had Saturn author of his family. But this old peaceful prince, as Heav''n decreed, Was blest with no male issue to succeed: His sons in blooming youth were snatch''d by fate; One only daughter heir''d the royal state. Fir''d with her love, and with ambition led, The neighb''ring princes court her nuptial bed.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_GRR_FIELDS_PUNISHMENT_VIRGIL','ENT_GRR_FIELDS_PUNISHMENT','SRC_VIRGIL_AENEID','Virgil, Aeneid','Virgil, Aeneid','Not far from thence, the Mournful Fields appear So call''d from lovers that inhabit there. The souls whom that unhappy flame invades, In secret solitude and myrtle shades Make endless moans, and, pining with desire, Lament too late their unextinguish''d fire. Here Procris, Eriphyle here he found, Baring her breast, yet bleeding with the wound Made by her son. He saw Pasiphae there, With Phaedra''s ghost, a foul incestuous pair.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_GRR_MOURNING_FIELDS_VIRGIL','ENT_GRR_MOURNING_FIELDS','SRC_VIRGIL_AENEID','Virgil, Aeneid','Virgil, Aeneid','Not far from thence, the Mournful Fields appear So call''d from lovers that inhabit there. The souls whom that unhappy flame invades, In secret solitude and myrtle shades Make endless moans, and, pining with desire, Lament too late their unextinguish''d fire. Here Procris, Eriphyle here he found, Baring her breast, yet bleeding with the wound Made by her son. He saw Pasiphae there, With Phaedra''s ghost, a foul incestuous pair.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_GRR_PLAIN_LETHE_VIRGIL','ENT_GRR_PLAIN_LETHE','SRC_VIRGIL_AENEID','Virgil, Aeneid','Virgil, Aeneid','The god was wroth, and at his temples threw A branch in Lethe dipp''d, and drunk with Stygian dew: The pilot, vanquish''d by the pow''r divine, Soon clos''d his swimming eyes, and lay supine. Scarce were his limbs extended at their length, The god, insulting with superior strength, Fell heavy on him, plung''d him in the sea, And, with the stern, the rudder tore away. Headlong he fell, and, struggling in the main, Cried out for helping hands, but cried in vain.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_GRR_UNDERWORLD_VIRGIL','ENT_GRR_UNDERWORLD','SRC_VIRGIL_AENEID','Virgil, Aeneid','Virgil, Aeneid','"By destiny compell''d, and in despair, The Greeks grew weary of the tedious war, And by Minerva''s aid a fabric rear''d, Which like a steed of monstrous height appear''d: The sides were plank''d with pine; they feign''d it made For their return, and this the vow they paid. Thus they pretend, but in the hollow side Selected numbers of their soldiers hide: With inward arms the dire machine they load, And iron bowels stuff the dark abode.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ROM_PLUTO_VIRGIL','ENT_ROM_PLUTO','SRC_VIRGIL_AENEID','Virgil, Aeneid','Book 6','But let us haste our voyage to pursue: The walls of Pluto''s palace are in view; The gate, and iron arch above it, stands On anvils labour''d by the Cyclops'' hands. Before our farther way the Fates allow, Here must we fix on high the golden bough." She said, and thro'' the gloomy shades they pass''d, And chose the middle path.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
